/**
 * Injected by Vite at build time (see vite.config.ts). Declared rather than
 * imported because `define` performs a textual substitution — these identifiers
 * never exist at runtime, so nothing can import them.
 */
declare const __BUILD_SHA__: string;
declare const __BUILD_TIME__: string;
/** Default host for the lobby, from SANDLINE_HOST at build time; '' when unset. */
declare const __DEFAULT_HOST__: string;
